<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">manifests = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Cargo.toml&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># module-boundary markers</span></span>
